#!/usr/bin/env bash
# 001_Table.sh - the class table (generated by tools/unicode/gen_width.sh):
#   * the header: version 16.0.0, the five input URLs with a sha256 each;
#   * spot checks of class and width (the glibc 2.41 rules: marks and default
#     ignorables 0, East Asian W/F 2, the exceptions U+00AD 1, U+115F 2,
#     U+3248..324F 2, Hangul V/T jamo 0) and the cluster classes;
#   * the page table: 68 strings of 64 page letters (z n w x y m r, or '*'),
#     '*' exactly where __FV_UC_M has an entry, expanding to 256 letters;
#   * the class sets that must be exact: r = U+1F1E6..1F1FF, m = U+1F3FB..1F3FF;
#   * bad arguments (rc 2, rc 1 above U+10FFFF, RESULT ''), leading zeros,
#     charWidth for every class, the lazy page expansion.

source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/fvu_testlib.sh"
fvu_init "$(basename "$0" .sh)" "$@"

kt_test_section "001: the table"

kt_test_start "version 16.0.0 (function and generated global)"
fv.unicode.version
if [[ $RESULT == 16.0.0 && $__FV_UC_VERSION == 16.0.0 ]]; then kt_test_pass "ok"; else kt_test_fail "RESULT=$RESULT"; fi

kt_test_start "the generated block's header names the five inputs with their sha256, in order"
hdr=''
while IFS= read -r l; do
    if [[ $l =~ ^#\ \ \ [0-9a-f]{64}\ (https://www\.unicode\.org/Public/16\.0\.0/ucd/[A-Za-z/-]+\.txt)$ ]]; then hdr+="${BASH_REMATCH[1]##*/ucd/} "; fi
done < "$FVU_UNIT"
want='EastAsianWidth.txt UnicodeData.txt DerivedCoreProperties.txt HangulSyllableType.txt emoji/emoji-data.txt '
nb=0 ne=0
while IFS= read -r l; do
    [[ $l == '# BEGIN GENERATED'* ]] && nb=$(( nb + 1 ))
    [[ $l == '# END GENERATED'* ]] && ne=$(( ne + 1 ))
done < "$FVU_UNIT"
if [[ $hdr == "$want" && $nb == 1 && $ne == 1 ]]; then kt_test_pass "ok"; else kt_test_fail "inputs [$hdr] markers $nb/$ne"; fi

# HEX:CLASS:WIDTH
SPOTS='0000:n:1 0041:n:1 007F:n:1 00A9:x:1 00AD:n:1 00E9:n:1 0301:z:0 0378:n:1 0483:z:0
0600:n:1 1100:w:2 115F:w:2 1160:z:0 11A8:z:0 200B:z:0 200C:z:0 200D:z:0 2028:n:1 2060:z:0
20E3:z:0 231A:y:2 2500:n:1 25FD:y:2 2764:x:1 2E80:w:2 3000:w:2 302A:z:0 303F:n:1 3099:z:0
3164:z:0 3248:w:2 324F:w:2 3250:w:2 4E00:w:2 9FFF:w:2 AC00:w:2 D7A3:w:2 D7B0:z:0 D7C7:n:1
D7CB:z:0 D7FC:n:1 FE0E:z:0 FE0F:z:0 FEFF:z:0 FF21:w:2 FFA0:z:0 FFFD:n:1 1F1E6:r:1 1F1FF:r:1
1F3FB:m:2 1F3FF:m:2 1F600:y:2 1F9D1:y:2 20000:w:2 2A6DF:w:2 30000:w:2 E0001:z:0 E0020:z:0
E007F:z:0 E0100:z:0 E01EF:z:0 F0000:n:1 10FFFF:n:1'
kt_test_start "spot checks: class and width of $(wc -w <<<"$SPOTS") code points"
bad=''
for e in $SPOTS; do
    h=${e%%:*} k=${e#*:} k=${k%:*} w=${e##*:}
    fv.unicode.charClass "$(( 16#$h ))" || bad+=" U+$h rc$?"
    [[ $RESULT == "$k" ]] || bad+=" U+$h class $RESULT (want $k)"
    fv.unicode.charWidth "$(( 16#$h ))" || bad+=" U+$h width rc$?"
    [[ $RESULT == "$w" ]] || bad+=" U+$h width $RESULT (want $w)"
done
if [[ -z $bad ]]; then kt_test_pass "ok"; else kt_test_fail "$bad"; fi

kt_test_start "the page table: 68 strings of 64 letters z n w x y m r or '*' (4352 pages)"
bad='' all=''
(( ${#__FV_UC_P[@]} == 68 )) || bad+=" ${#__FV_UC_P[@]} strings"
for (( i = 0; i < 68; i++ )); do
    [[ ${#__FV_UC_P[i]} == 64 && ${__FV_UC_P[i]} != *[!znwxymr*]* ]] || bad+=" P[$i]='${__FV_UC_P[i]-}'"
    all+=${__FV_UC_P[i]-}
done
stars=${all//[!*]/} n=${#stars}
if [[ -z $bad ]]; then kt_test_pass "$n mixed pages"; else kt_test_fail "$bad"; fi

kt_test_start "'*' exactly where __FV_UC_M has an entry; each expands to 256 letters and is not uniform"
bad=''
(( n == ${#__FV_UC_M[@]} )) || bad+=" $n '*' pages, ${#__FV_UC_M[@]} entries"
for p in "${!__FV_UC_M[@]}"; do
    [[ ${all:p:1} == '*' ]] || bad+=" M[$p] for a page that is not '*'"
    [[ ${__FV_UC_M[p]} =~ ^([znwxymr][0-9]+)+$ ]] || bad+=" M[$p] is not run-length letters"
    fvu_page "$p"
    [[ ${#FVU_PAGE} == 256 && $FVU_PAGE != *[!znwxymr]* ]] || bad+=" page $p expands to ${#FVU_PAGE}"
    [[ ${FVU_PAGE//${FVU_PAGE:0:1}/} == '' ]] && bad+=" page $p is uniform"
done
if [[ -z $bad ]]; then kt_test_pass "${#__FV_UC_M[@]} mixed pages"; else kt_test_fail "$bad"; fi

# fvu_set CLASS -> SET: every code point of that class, as "HEX..HEX" ranges
fvu_set() {
    local p i c start=-1 prev=-2 k
    SET=''
    for (( p = 0; p < 4352; p++ )); do
        k=${__FV_UC_P[p >> 6]:p % 64:1}
        [[ $k == "$1" || ( $k == '*' && ${__FV_UC_M[p]} == *"$1"* ) ]] || continue
        fvu_page "$p"
        for (( i = 0; i < 256; i++ )); do
            [[ ${FVU_PAGE:i:1} == "$1" ]] || continue
            c=$(( p * 256 + i ))
            if (( c != prev + 1 )); then
                if (( start >= 0 )); then printf -v SET '%s%X..%X ' "$SET" "$start" "$prev"; fi
                start=$c
            fi
            prev=$c
        done
    done
    if (( start >= 0 )); then printf -v SET '%s%X..%X' "$SET" "$start" "$prev"; fi
}
kt_test_start "class r is exactly U+1F1E6..1F1FF, class m exactly U+1F3FB..1F3FF"
fvu_set r; r=$SET
fvu_set m; m=$SET
if [[ $r == 1F1E6..1F1FF && $m == 1F3FB..1F3FF ]]; then kt_test_pass "ok"; else kt_test_fail "r=[$r] m=[$m]"; fi

kt_test_start "a whole Hangul syllable block: L 2, V 0, T 0; the syllable 2"
r=''
for h in 1100 1161 11A8 AC01 A960 D7B0 D7CB; do fv.unicode.charWidth "$(( 16#$h ))"; r+="$RESULT"; done
if [[ $r == 2002200 ]]; then kt_test_pass "ok"; else kt_test_fail "$r"; fi

# U+0663, an Arabic-Indic digit: [[:digit:]] matches it on macOS and FreeBSD
# (iswdigit); the unit's explicit [0123456789] does not
kt_test_start "bad arguments: not digits -> rc 2, above U+10FFFF -> rc 1, RESULT '' each time"
r=''
for a in '' x -1 +65 ' 65' 6.5 0x41 12345678 '65 ' $'\xd9\xa3'; do
    RESULT=junk; fv.unicode.charClass "$a"; r+="$?[$RESULT] "
done
RESULT=junk; fv.unicode.charClass 1114112; r+="$?[$RESULT] "
RESULT=junk; fv.unicode.charWidth 1114112; r+="$?[$RESULT] "
RESULT=junk; fv.unicode.charWidth x; r+="$?[$RESULT] "
RESULT=junk; fv.unicode.charClass; r+="$?[$RESULT]"
want='2[] 2[] 2[] 2[] 2[] 2[] 2[] 2[] 2[] 2[] 1[] 1[] 2[] 2[]'
if [[ $r == "$want" ]]; then kt_test_pass "ok"; else kt_test_fail "got  $r"$'\n'"want $want"; fi

kt_test_start "leading zeros are decimal: 0000065 = 'A', 0019968 = U+4E00, 1114111 = U+10FFFF"
r=''
fv.unicode.charClass 0000065; r+=$RESULT
fv.unicode.charClass 0019968; r+=$RESULT
fv.unicode.charClass 1114111; r+=$RESULT
fv.unicode.charClass 0; r+=$RESULT
if [[ $r == nwnn ]]; then kt_test_pass "ok"; else kt_test_fail "$r"; fi

kt_test_start "charWidth maps every class: z 0, n x r 1, w y m 2"
r=''
for h in 301 41 A9 1F1E6 4E00 1F600 1F3FB; do fv.unicode.charClass "$(( 16#$h ))"; r+=$RESULT; fv.unicode.charWidth "$(( 16#$h ))"; r+="$RESULT "; done
if [[ $r == 'z0 n1 x1 r1 w2 y2 m2 ' ]]; then kt_test_pass "ok"; else kt_test_fail "$r"; fi

kt_test_start "a mixed page is expanded on its first lookup into 16 chunks, once; a subshell's expansion stays there"
p=$(( 0x1F6 ))
for (( i = 0; i < 16; i++ )); do unset "__FV_UC_E[p * 16 + i]"; done
( fv.unicode.charClass $(( 0x1F600 )); [[ -n ${__FV_UC_E[p * 16 + 15]-} ]] ) && sub=ok || sub=no
before=${__FV_UC_E[p * 16]-unset}
fv.unicode.charClass $(( 0x1F600 )); a=$RESULT
e1=''
for (( i = 0; i < 16; i++ )); do e1+="${__FV_UC_E[p * 16 + i]-}|"; done
fv.unicode.charClass $(( 0x1F650 )); b=$RESULT
e2=''
for (( i = 0; i < 16; i++ )); do e2+="${__FV_UC_E[p * 16 + i]-}|"; done
if [[ $sub == ok && $before == unset && ${#e1} == 272 && $e1 == "$e2" && $a == y && $b == n ]]; then kt_test_pass "ok"
else kt_test_fail "sub=$sub before=$before len=${#e1} a=$a b=$b"; fi

kt_test_log "001_Table.sh completed"
